mapper.select:


    del_flag = '0'
     AND abnormal_no LIKE CONCAT('%', #{abnormalNo}, '%')
     AND work_order_no LIKE CONCAT('%', #{workOrderNo}, '%')
     AND abnormal_type = #{abnormalType}
     AND severity = #{severity}
     AND status = #{status}
     AND report_by LIKE CONCAT('%', #{reportBy}, '%')
     AND date(create_time) >= #{params.beginTime}
     AND date(create_time) <= #{params.endTime}

ORDER BY abnormal_id DESC
